/** Read caller-supplied decryption keys from the local MCP environment, never tool arguments. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    readSaveDecodeOptions
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { readFileSync, statSync } from 'node:fs'

export function readSaveDecodeOptions() {
  const file = process.env.TOWER_SAVE_KEYS_FILE
  if (!file) return undefined
  try {
    if (statSync(file).size > 4096) throw new Error('Key file exceeds the size limit')
    return { keys: JSON.parse(readFileSync(file, 'utf8')) }
  } catch {
    throw new Error('Unable to read TOWER_SAVE_KEYS_FILE as a key JSON file.')
  }
}
